    public void insertProjTransList()
    {
        VendInvoiceTrans    vendInvoiceTrans;
        PurchTable          purchTable;
        PurchLine           purchLine;

        next insertProjTransList();

        if (projEmplTrans.vendInvoiceTrans)
        {
            vendInvoiceTrans = VendInvoiceTrans::findRecId(projEmplTrans.vendInvoiceTrans);
            purchTable       = PurchTable::find(vendInvoiceTrans.PurchID);
            purchline        = vendInvoiceTrans.purchLine();

            ttsbegin;
            tmpProjTransList.selectForUpdate(true);
            tmpProjTransList.METPONum       = purchline.PurchId;
            tmpProjTransList.METVendName    = VendTable::find(purchTable.OrderAccount).name();
            tmpProjTransList.METTransDate   = vendInvoiceTrans.InvoiceDate;
            tmpProjTransList.METGLAccount   = this.getProjPosting(ProjCategory::find(purchline.ProjCategoryId).Name);
            tmpProjTransList.update();
            ttscommit;
        }
        
    }

    public DimensionDisplayValue getProjPosting(ProjCategoryName _projCategoryName)
    {
        ProjPosting projPosting;

        select firstonly LedgerDimension from  projPosting
            where projPosting.ProjCategoryRelation == _projCategoryName;

        return LedgerDimensionFacade::getDisplayValueForLedgerDimension(ProjPosting.LedgerDimension);
    }
